eseries_pool_read_latency{array=~"$Array",datacenter=~"$Datacenter",pool=~"$Pool"}
and on (datacenter, pool, array)
  topk(
    $TopResources,
    max by (datacenter, pool, array) (
      avg_over_time(
        eseries_pool_read_latency{array=~"$Array",datacenter=~"$Datacenter",pool=~"$Pool"}[3h] @ end()
      )
    )
  )

